const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.report}"/></svg>`;
const esc=(x)=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count=x=>Math.round(x).toLocaleString('id-ID');
const percent=x=>x.toLocaleString('id-ID',{minimumFractionDigits:1,maximumFractionDigits:1})+'%';
const money=x=>'Rp'+Math.round(x).toLocaleString('id-ID');
const compact=x=>'Rp'+(Math.abs(x)>=1e9?(x/1e9).toLocaleString('id-ID',{maximumFractionDigits:2})+' miliar':Math.abs(x)>=1e6?(x/1e6).toLocaleString('id-ID',{maximumFractionDigits:1})+' jt':Math.round(x).toLocaleString('id-ID'));
const sum=(rows,k)=>rows.reduce((a,r)=>a+r[k],0);
const pages={reference:['Ringkasan Finance 2025','Central Fashion Store · kompilasi unit 2025 dibanding 2024.','report'],overview:['Ringkasan eksekutif','Dari kinerja perusahaan ke keputusan yang perlu diambil.','grid'],stores:['Kinerja toko','Bandingkan pertumbuhan, margin, dan kecukupan stok setiap toko.','store'],inventory:['Barang & pembelian','Lihat modal yang tertahan di stok dan kelancaran pasokan.','boxes'],finance:['Kas & laba','Baca hasil usaha, uang yang tersedia, dan kewajiban terdekat.','wallet'],customers:['Pelanggan & promosi','Pahami kualitas penjualan dan kontribusi pelanggan member.','promo'],people:['Tim & aset','Pantau kapasitas tim dan kesiapan tempat usaha.','users'],coverage:['Cakupan data','Hasil pembacaan database lokal dan batas kesiapan setiap metrik.','database'],saved:['Laporan tersimpan','Contoh akses ke report lintas periode dan sudut pandang.','archive']};
const rawStores=[
 [1,212,184,42.1,620,5840,15,96.1,2,1,18,21], [2,184,165,40.6,571,5390,14,97.5,1,2,20,19],
 [3,126,139,38.2,610,4380,12,92.8,2,4,24,29], [4,174,150,43.1,492,4190,13,98.2,1,0,13,15],
 [5,162,146,40.2,565,4080,13,96.4,2,1,16,20], [6,143,129,41.4,536,3870,12,97.1,1,2,15,20],
 [7,236,192,43.7,660,6270,18,98.6,2,0,20,20], [8,129,116,39.8,548,3900,12,96.2,1,1,17,23],
 [9,97,112,36.7,661,3450,11,91.7,2,3,19,35], [10,149,131,41.8,527,3850,12,97.3,2,1,14,19],
 [11,118,121,39.1,585,3910,11,94.6,1,2,17,26], [12,135,119,40.7,552,3770,12,97.7,1,1,16,21],
 [13,107,96,39.5,480,3130,10,96.9,1,1,15,21]
];
// Monetary fields are whole IDR (matching @itulah/contract/money), never cents.
const baseStores=rawStores.map(([n,net,prior,margin,baskets,stock,staff,attendance,repairs,vacancies,slow,cover])=>({id:'store-'+String(n).padStart(2,'0'),name:'Store '+String(n).padStart(2,'0'),net:net*1e6,prior:prior*1e6,margin,baskets,stock,staff,attendance,repairs,vacancies,slow,cover,cogs:Math.round(net*1e6*(1-margin/100)),units:Math.round(baskets*1.83),overdue:(n===3?19:n===9?22:n===11?14:3)*1e6,cash:(35+n*4)*1e6,memberShare:40+(n*3)%21}));
const state={page:'overview',period:'sep',scope:'all',compare:true,storeFilter:'all',search:'',sort:'net',descending:true,dbSearch:'',dbFilter:'all'};
function model(){
 const rows=baseStores.filter(r=>state.scope==='all'||r.id===state.scope).map(r=>{
  if(state.period==='sep')return {...r};
  const net=Math.round(r.prior*31/25),prior=Math.round(net/(1+(Number(r.id.slice(-2))%5+3)/100)),baskets=Math.round(r.baskets*31/25*.91);
  return {...r,net,prior,baskets,units:Math.round(baskets*1.81),cogs:Math.round(net*(1-(r.margin-.6)/100)),margin:r.margin-.6,stock:Math.round(r.stock*.94),attendance:Math.min(100,r.attendance+.3),overdue:Math.round(r.overdue*.87)};
 });
 const net=sum(rows,'net'),prior=sum(rows,'prior'),cogs=sum(rows,'cogs'),stock=sum(rows,'stock'),units=sum(rows,'units'),baskets=sum(rows,'baskets'),days=state.period==='sep'?25:31;
 const gross=net-cogs,bookRevenue=Math.round(net*.982),bookCogs=Math.round(cogs*.982),bookGross=bookRevenue-bookCogs,opex=Math.round(net*.234),otherOpex=Math.round(net*.021),nonOperating=-Math.round(net*.006),tax=Math.round((bookGross-opex-otherOpex+nonOperating)*.20);
 const inventory=stock*95000,slowUnits=Math.round(rows.reduce((v,r)=>v+r.stock*r.slow/100,0)),staff=sum(rows,'staff');
 return {rows,net,prior,cogs,stock,units,baskets,days,gross,bookRevenue,bookCogs,bookGross,margin:gross/net*100,growth:(net/prior-1)*100,opex,otherOpex,nonOperating,tax,profit:bookGross-opex-otherOpex+nonOperating-tax,inventory,slowUnits,stockDays:stock/(units/days),staff,attendance:rows.reduce((a,r)=>a+r.attendance*r.staff,0)/staff,overdue:sum(rows,'overdue'),cash:sum(rows,'cash'),memberShare:rows.reduce((v,r)=>v+r.memberShare*r.net,0)/net};
}
const periodLabel=()=>state.period==='sep'?'01–25 September 2026':'01–31 Agustus 2026';
const beforeLabel=()=>state.period==='sep'?'01–25 Agustus 2026':'01–31 Juli 2026';
const scopeLabel=()=>state.scope==='all'?'13 toko':baseStores.find(r=>r.id===state.scope).name;
const pill=(text,tone='')=>`<span class="pill ${tone}">${text}</span>`;
function delta(n,suffix='vs periode lalu'){return state.compare?`<span class="delta ${n>=0?'positive':'negative'}">${n>=0?'↗':'↘'} ${percent(Math.abs(n))}</span> <span>${suffix}</span>`:'<span>Perbandingan disembunyikan</span>';}
function kpi(label,value,foot,key){return `<button class="card kpi" data-metric="${key}" aria-label="Definisi ${label}"><span class="kpi-label">${label}${icon('info')}</span><span class="kpi-value">${value}</span><span class="kpi-foot">${foot}</span></button>`;}
const cardHead=(title,sub='',action='')=>`<div class="card-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
const navLink=(key,text)=>`<a href="#${key}" class="text-link">${text}${icon('arrow')}</a>`;
function setupShell(){
 const domainRows=[['home','Home'],['shirt','Merchandise'],['boxes','Inventory'],['truck','Ops'],['promo','Marketing'],['buy','Buying'],['store','Selling'],['bank','Finance'],['wallet','Finance New'],['users','HR'],['chat','GA']];
 document.querySelector('#rail').innerHTML=`<div class="rail-main">${domainRows.map(([i,t])=>`<button class="rail-item" data-shell="${t}" title="${t} · konteks aplikasi">${icon(i)}<span>${t}</span></button>`).join('')}</div><div class="rail-bottom"><button class="icon-btn" data-shell="Library" aria-label="Library">${icon('folder')}</button><a class="icon-btn active" href="#overview" aria-label="Reports" aria-current="page">${icon('report')}</a><button class="icon-btn" data-shell="System" aria-label="System">${icon('settings')}</button><button class="icon-btn fold" data-action="navigation" aria-label="Lipat sidebar">${icon('panel')}</button></div>`;
 document.querySelector('#report-nav').innerHTML=Object.entries(pages).filter(([k])=>!['saved','coverage','reference'].includes(k)).map(([k,[name,,i]])=>`<a class="nav-item" href="#${k}" data-nav="${k}">${icon(i)}${k==='overview'?'Ringkasan':name}</a>`).join('');
 document.querySelector('#library-nav').innerHTML=['reference','coverage','saved'].map(k=>`<a class="nav-item" href="#${k}" data-nav="${k}">${icon(pages[k][2])}${pages[k][0]}</a>`).join('');
 document.querySelector('#top-tools').innerHTML=`<button class="icon-btn" data-shell="Discussions" aria-label="Diskusi">${icon('chat')}</button><button class="icon-btn" data-shell="Chat" aria-label="Chat">${icon('chat')}</button><button class="icon-btn" data-shell="Notifications" aria-label="Notifikasi">${icon('bell')}</button><button class="button ask-context" data-shell="Ask">${icon('spark')}Ask</button>`;
 document.querySelector('#scope').innerHTML='<option value="all">Semua toko</option>'+baseStores.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');
 document.querySelector('#calendar-icon').innerHTML=icon('calendar');document.querySelector('#store-icon').innerHTML=icon('store');document.querySelector('#nav-toggle').innerHTML=icon('menu');document.querySelector('#help-button').innerHTML=icon('info');document.querySelector('#print-button').innerHTML=icon('print')+'Cetak report';
}
function trendChart(m){
 const weights=Array.from({length:m.days},(_,i)=>1+(i%7===5?.55:i%7===6?.4:0)+Math.sin(i*1.63)*.17+i*.011);
 const prevWeights=weights.map((x,i)=>x*(.82+Math.cos(i*.9)*.17));
 const totals=(ws,t)=>{const s=ws.reduce((a,b)=>a+b,0),a=ws.map(v=>Math.round(v/s*t));a[a.length-1]+=t-a.reduce((x,y)=>x+y,0);return a;};
 const values=totals(weights,m.net),before=totals(prevWeights,m.prior),top=Math.ceil(Math.max(...values,...before)/1e7)*1e7;
 const point=(v,i)=>[42+i*(550/(m.days-1)),172-v/top*143];
 const line=vs=>vs.map((v,i)=>point(v,i).join(',')).join(' '),last=point(values.at(-1),m.days-1);
 return `<section class="card">${cardHead('Penjualan bersih','Sesudah diskon & retur · sebelum pajak',navLink('stores','Kinerja toko'))}<div class="chart-wrap"><div class="chart-top"><span>Juta rupiah · harian</span><div class="legend"><span><i></i>${state.period==='sep'?'September':'Agustus'}</span>${state.compare?`<span class="previous"><i></i>${state.period==='sep'?'Agustus':'Juli'}</span>`:''}</div></div><svg class="trend" viewBox="0 0 620 210" role="img" aria-label="Tren simulasi penjualan bersih ${periodLabel()}, total ${money(m.net)}${state.compare?', dibanding '+money(m.prior):''}">${[0,.5,1].map(f=>`<line class="grid-line" x1="42" x2="603" y1="${172-f*143}" y2="${172-f*143}"/><text x="30" y="${176-f*143}" text-anchor="end">${count(top*f/1e6)}</text>`).join('')}<polygon class="area" points="42,172 ${line(values)} 592,172"/>${state.compare?`<polyline class="line-prior" points="${line(before)}"/>`:''}<polyline class="line-current" points="${line(values)}"/><circle cx="${last[0]}" cy="${last[1]}" r="3.5" fill="var(--canvas)" stroke="var(--accent)" stroke-width="2"/>${[0,Math.round((m.days-1)*.25),Math.round((m.days-1)*.5),Math.round((m.days-1)*.75),m.days-1].map(i=>`<text x="${point(0,i)[0]}" y="198" text-anchor="middle">${String(i+1).padStart(2,'0')} ${state.period==='sep'?'Sep':'Agu'}</text>`).join('')}</svg></div><div class="chart-summary"><span><strong>${count(m.baskets)}</strong> transaksi · <strong>${count(m.units)}</strong> unit</span><span>Rata-rata struk <strong>${compact(m.net/m.baskets)}</strong></span></div></section>`;
}
function priorities(m){
 const declining=m.rows.filter(r=>r.net<r.prior).sort((a,b)=>(a.net/a.prior)-(b.net/b.prior));
 const stockTitle=m.slowUnits?`${count(m.slowUnits)} unit berumur >90 hari`:'Stok berumur panjang terkendali';
 return `<section class="card">${cardHead('Perlu perhatian','Tiga hal untuk dibawa ke rapat',pill('3 fokus','warn'))}<a href="#inventory" class="priority-item" style="text-decoration:none"><span class="priority-mark">01</span><div><h3>${stockTitle}</h3><p>${compact(m.slowUnits*95000)} modal tertahan. Tinjau redistribusi sebelum pembelian berikutnya.</p><small>Buying & Commercial · tinjau minggu ini</small></div>${icon('chevron')}</a><a href="#finance" class="priority-item" style="text-decoration:none"><span class="priority-mark bad">02</span><div><h3>${compact(m.overdue)} utang lewat jatuh tempo</h3><p>Urutkan pembayaran menurut tanggal jatuh tempo dan saldo terbuka.</p><small>Finance · tindak lanjut pembayaran</small></div>${icon('chevron')}</a><a href="#stores" class="priority-item" style="text-decoration:none"><span class="priority-mark">03</span><div><h3>${declining.length?declining.length+' toko mengalami penurunan':'Jaga momentum toko'}</h3><p>${declining.length?declining.map(s=>s.name).join(', ')+'. Periksa kontribusi produk dan ketersediaan stok.':'Penjualan tumbuh di cakupan ini. Pastikan stok tersedia untuk akhir pekan.'}</p><small>Selling · evaluasi per toko</small></div>${icon('chevron')}</a></section>`;
}
function storeTable(m){return `<section class="card">${cardHead('Perbandingan toko',`${m.rows.length} toko · angka simulasi · klik toko untuk menelusuri`,state.page==='overview'?navLink('stores','Lihat kinerja'):pill('Penjualan operasional'))}<div class="table-toolbar"><label class="search">${icon('search')}<input type="search" id="store-search" placeholder="Cari toko…" aria-label="Cari toko" value="${esc(state.search)}"></label><div class="segmented" aria-label="Filter kinerja"><button data-store-filter="all" aria-pressed="${state.storeFilter==='all'}">Semua</button><button data-store-filter="declining" aria-pressed="${state.storeFilter==='declining'}">Menurun</button></div></div><div class="table-scroll"><table><thead><tr><th>Toko</th><th class="num"><button data-sort="net">Penjualan bersih ${icon('sort')}</button></th><th class="num"><button data-sort="growth">Perubahan ${icon('sort')}</button></th><th class="num"><button data-sort="margin">Margin kotor ${icon('sort')}</button></th><th class="num">Struk</th><th class="num">Cakupan stok</th><th>Kondisi</th></tr></thead><tbody id="store-body">${storeRows(m)}</tbody></table></div><div class="table-foot"><span id="store-count"></span><span>Margin tertimbang · cakupan stok = unit tersedia / laju jual</span></div></section>`;}
function selectedStoreRows(m){return m.rows.filter(r=>r.name.toLowerCase().includes(state.search.toLowerCase())&&(state.storeFilter!=='declining'||r.net<r.prior)).sort((a,b)=>{const get=r=>state.sort==='growth'?r.net/r.prior-1:r[state.sort];return (get(a)-get(b))*(state.descending?-1:1);});}
function storeRows(m){const rows=selectedStoreRows(m);return rows.length?rows.map(r=>`<tr data-store="${r.id}"><td><button class="row-title" data-store="${r.id}">${icon('store')}${r.name}</button></td><td class="num">${compact(r.net)}</td><td class="num">${state.compare?`<span class="${r.net>=r.prior?'positive':'negative'}">${r.net>=r.prior?'+':'−'}${percent(Math.abs((r.net/r.prior-1)*100))}</span>`:'—'}</td><td class="num">${percent(r.margin)}</td><td class="num">${count(r.baskets)}</td><td class="num">${count(r.stock/(r.units/m.days))} hari</td><td>${r.net<r.prior?pill('Tinjau penjualan','warn'):pill('Bertumbuh','ok')}</td></tr>`).join('')+`<tr class="summary-total"><td>Total ${rows.length} toko</td><td class="num">${compact(sum(rows,'net'))}</td><td class="num">${state.compare?percent((sum(rows,'net')/sum(rows,'prior')-1)*100):'—'}</td><td class="num">${percent((sum(rows,'net')-sum(rows,'cogs'))/sum(rows,'net')*100)}</td><td class="num">${count(sum(rows,'baskets'))}</td><td class="num">${count(sum(rows,'stock')/(sum(rows,'units')/m.days))} hari</td><td></td></tr>`:`<tr><td colspan="7" class="empty">Tidak ada toko yang cocok. Ubah pencarian atau pilih “Semua”.</td></tr>`;}
function updateStoreTable(){const m=model();document.querySelector('#store-body').innerHTML=storeRows(m);document.querySelectorAll('[data-sort]').forEach(b=>b.closest('th').setAttribute('aria-sort',b.dataset.sort===state.sort?(state.descending?'descending':'ascending'):'none'));document.querySelector('#store-count').textContent=`${selectedStoreRows(m).length} dari ${m.rows.length} toko`;document.querySelectorAll('[data-store-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.storeFilter===state.storeFilter));decorateTables();}
function overview(m){
 return `<section class="card brief"><span class="brief-mark">${icon('report')}</span><div><div class="eyebrow">CATATAN PERIODE INI</div><h2>${m.growth>=0?'Penjualan tumbuh. Perputaran stok tetap perlu perhatian.':'Penjualan melemah. Tinjau stok dan komposisi produk.'}</h2><p>${state.compare?`Penjualan ${m.growth>=0?'naik':'turun'} <strong>${percent(Math.abs(m.growth))}</strong> dibanding ${beforeLabel()}. `:''}Margin kotor <strong>${percent(m.margin)}</strong>, sementara <strong>${percent(m.slowUnits/m.stock*100)}</strong> stok toko berumur lebih dari 90 hari.</p></div>${pill('Skenario desain')}</section><div class="kpi-grid">${kpi('Penjualan bersih',compact(m.net),delta(m.growth),'sales')}${kpi('Laba kotor dagang',compact(m.gross),`Margin ${percent(m.margin)} · biaya barang terjual`,'margin')}${kpi('Nilai stok toko',compact(m.inventory),`${count(m.stock)} unit · ${count(m.stockDays)} hari cakupan`,'stock')}${kpi('Kas & bank toko',compact(m.cash),'Saldo buku pada akhir periode','cash')}</div><div class="grid-main">${trendChart(m)}${priorities(m)}</div>${storeTable(m)}<div class="grid-three bottom-strip"><a class="card signal-card" href="#finance" style="text-decoration:none"><span class="signal-top">${icon('wallet')}Kas & laba</span><strong>${compact(m.profit)} laba bersih toko</strong><p>Angka buku mengikuti jurnal yang sudah tercatat; belum termasuk overhead HO.</p><span class="text-link">Baca jembatan laba ${icon('arrow')}</span></a><a class="card signal-card" href="#people" style="text-decoration:none"><span class="signal-top">${icon('users')}Tim & aset</span><strong>${percent(m.attendance)} kehadiran tim</strong><p>${count(m.staff)} karyawan aktif · ${count(sum(m.rows,'repairs'))} pekerjaan perbaikan terbuka.</p><span class="text-link">Lihat kesiapan operasional ${icon('arrow')}</span></a><a class="card signal-card" href="#coverage" style="text-decoration:none"><span class="signal-top">${icon('shield')}Cakupan data</span><strong>Angka ini adalah simulasi</strong><p>Periksa tabel, sumber metrik, dan bagian yang belum siap di database lokal.</p><span class="text-link">Lihat hasil pemeriksaan ${icon('arrow')}</span></a></div>`;
}
function stores(m){return `<div class="kpi-grid">${kpi('Penjualan bersih',compact(m.net),delta(m.growth),'sales')}${kpi('Transaksi',count(m.baskets),`${count(m.units)} unit terjual`,'basket')}${kpi('Rata-rata struk',compact(m.net/m.baskets),`${(m.units/m.baskets).toFixed(2).replace('.',',')} unit per transaksi`,'basket')}${kpi('Toko menurun',`${m.rows.filter(r=>r.net<r.prior).length} / ${m.rows.length}`,'Dibanding periode sebelumnya','comparison')}</div>${storeTable(m)}<div class="grid-main bottom-strip">${trendChart(m)}<section class="card">${cardHead('Cara membaca perbandingan','Periode, populasi, dan cakupan yang sama')}<div class="card-pad plain-note"><p>September dibaca sampai tanggal 25, lalu dibandingkan dengan 25 hari pertama Agustus. Toko tanpa transaksi tetap tampil sebagai nol bila sinkronisasi lengkap.</p><div class="section-note">Status toko dan kesegaran data perlu dibaca sebelum menyimpulkan penurunan. Data yang belum masuk tidak boleh dianggap penjualan nol.</div><button class="text-link" data-metric="comparison">Lihat definisi ${icon('arrow')}</button></div></section></div>`;}
function bars(rows){const max=Math.max(...rows.map(r=>r[1]));return rows.map(([label,value,display,tone])=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><span style="width:${value/max*100}%;${tone?'background:var(--'+tone+')':''}"></span></div><span class="value">${display||count(value)}</span></div>`).join('');}
function inventory(m){const young=Math.round(m.stock*.42),medium=Math.round(m.stock*.27),old=m.slowUnits,remaining=m.stock-young-medium-old;const openPo=Math.round(m.inventory*.28),incoming=Math.round(m.stock*.16);return `<div class="kpi-grid">${kpi('Stok toko',count(m.stock),`${compact(m.inventory)} pada biaya perolehan`,'stock')}${kpi('Stok >90 hari',count(old),`${percent(old/m.stock*100)} dari unit tersedia`,'aging')}${kpi('Cakupan stok',count(m.stockDays)+' hari','Menggunakan laju jual periode terpilih','cover')}${kpi('Komitmen pembelian',compact(openPo),'Nilai PO diterbitkan yang belum diterima','purchase')}</div><div class="grid-two"><section class="card">${cardHead('Umur stok toko','Umur sejak penerimaan lapisan biaya, bukan last movement')}<div class="card-pad">${bars([['0–30 hari',young,count(young)+' unit'],['31–60 hari',medium,count(medium)+' unit'],['61–90 hari',remaining,count(remaining)+' unit','a-orange'],['>90 hari',old,count(old)+' unit','warn']])}<div class="section-note">${compact(old*95000)} berada di stok berumur >90 hari. Umur stok yang belum punya lapisan penerimaan ditampilkan sebagai “belum diketahui”.</div><button class="text-link" data-metric="aging">Definisi umur stok ${icon('arrow')}</button></div></section><section class="card">${cardHead('Barang dalam perjalanan','Alur pemenuhan ke cakupan toko yang dipilih')}<div class="card-pad"><ul class="key-values"><li><span>PO terbuka</span><strong>${compact(openPo)}</strong></li><li><span>Menunggu pengiriman</span><strong>${count(Math.round(incoming*.4))} unit</strong></li><li><span>Dalam perjalanan</span><strong>${count(Math.round(incoming*.6))} unit</strong></li><li><span>Penerimaan belum lengkap</span>${pill(`${m.rows.length+2} baris`, 'warn')}</li></ul><p class="plain-note" style="margin-top:1rem">Stok di DC dan dalam perjalanan dipisahkan dari stok tersedia toko. Kuantitas dijumlahkan per tahap terakhir agar tidak terhitung dua kali.</p></div></section></div><section class="card">${cardHead('Komposisi barang','Sembilan divisi sesuai laporan Finance · contoh alokasi simulasi')}<div class="table-scroll"><table><thead><tr><th>Divisi</th><th class="num">Kontribusi penjualan</th><th class="num">Unit tersedia</th><th class="num">Nilai stok</th><th>Fokus</th></tr></thead><tbody>${actual.divisions.map(d=>[d.name,d.net/actual.divisionTotals.net,Number(d.code)===9?'Periksa klasifikasi & biaya':'Tinjau ketersediaan & umur stok']).map(([n,p,f])=>`<tr><td><strong>${n}</strong></td><td class="num">${compact(m.net*p)}</td><td class="num">${count(m.stock*p)}</td><td class="num">${compact(m.inventory*p)}</td><td>${f}</td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>Alokasi divisi untuk menguji tampilan, bukan hasil query produksi.</span><button class="text-link" data-metric="stock">Sumber stok ${icon('arrow')}</button></div></section>`;}
function finance(m){const due=Math.round(m.net*.135),grossOp=m.bookGross-m.opex,netOp=grossOp-m.otherOpex,beforeTax=netOp+m.nonOperating,postedRevenue=m.bookRevenue,gap=m.net-postedRevenue;return `<div class="kpi-grid">${kpi('Laba bersih toko',compact(m.profit),`${percent(m.profit/m.bookRevenue*100)} dari pendapatan buku · simulasi`,'profit')}${kpi('Kas & bank toko',compact(m.cash),'Saldo akhir periode dari buku besar','cash')}${kpi('Utang jatuh tempo 30 hari',compact(due),'Saldo terbuka menurut jadwal tagihan','payables')}${kpi('Utang lewat jatuh tempo',compact(m.overdue),'Tidak termasuk tagihan tanpa due date','payables')}</div><div class="grid-two"><section class="card">${cardHead('Dari penjualan ke laba','Hanya pendapatan & biaya yang sudah masuk buku',pill('Simulasi buku'))}<div class="card-pad"><ul class="key-values">${[['Penjualan bersih',m.bookRevenue],['Beban pokok penjualan',-m.bookCogs],['Laba usaha kotor',m.bookGross,'total'],['Beban usaha',-m.opex],['Gross operating profit',grossOp,'total'],['Beban usaha lainnya',-m.otherOpex],['Net operating profit',netOp,'total'],['Pendapatan / biaya non operasi',m.nonOperating],['Laba sebelum pajak',beforeTax,'total'],['Pajak penghasilan',-m.tax],['Laba bersih',m.profit,'total']].map(([l,v,c])=>`<li class="${c||''}"><span>${l}</span><strong class="num">${v<0?'('+compact(-v)+')':compact(v)}</strong></li>`).join('')}</ul><p class="plain-note" style="margin-top:1rem">Cakupan toko. Biaya HO dan eliminasi antarunit diperlukan sebelum disebut laba konsolidasi perusahaan.</p><button class="text-link" data-metric="profit" style="margin-top:.75rem">Definisi laba buku ${icon('arrow')}</button></div></section><div><section class="card">${cardHead('Penjualan & pembukuan','Contoh kondisi sebelum posting selesai',pill('Perlu rekonsiliasi','warn'))}<div class="card-pad"><ul class="key-values"><li><span>Penjualan operasional</span><strong>${compact(m.net)}</strong></li><li><span>Sudah masuk pembukuan</span><strong>${compact(postedRevenue)}</strong></li><li class="total"><span>Belum dibukukan</span><strong class="warning">${compact(gap)}</strong></li></ul><div class="section-note">Skenario: penjualan dan HPP sudah diposting 98,2%; beban periode sudah diposting penuh. Laba di kiri memakai penjualan yang sudah dibukukan. Penjualan yang belum diposting beserta biaya barangnya belum masuk laba; nilainya akan berubah setelah posting selesai.</div><button class="text-link" data-metric="reconciliation">Bagaimana selisih dijelaskan ${icon('arrow')}</button></div></section><section class="card" style="margin-top:1rem">${cardHead('Kewajiban yang perlu disiapkan','Urutkan pembayaran berdasarkan tanggal jatuh tempo')}<div class="card-pad">${bars([['Lewat tempo',m.overdue,compact(m.overdue),'warn'],['≤7 hari',due*.43,compact(due*.43)],['8–30 hari',due*.57,compact(due*.57)]])}<p class="plain-note">Kas buku belum sama dengan dana bebas. Giro beredar, dana terikat, dan pembayaran terjadwal perlu ditinjau sebelum keputusan pembayaran.</p></div></section></div></div>`;}
function customers(m){const memberNet=Math.round(m.net*m.memberShare/100),promoSales=Math.round(m.net*.28),discount=Math.round(promoSales*.115);return `<div class="kpi-grid">${kpi('Penjualan ke member',compact(memberNet),`${percent(m.memberShare)} dari penjualan bersih`,'members')}${kpi('Transaksi member',count(Math.round(m.baskets*.39)),'Identitas member tercatat pada transaksi','members')}${kpi('Penjualan dengan promo',compact(promoSales),'Satu transaksi dihitung sekali','promotion')}${kpi('Diskon promo',compact(discount),'Dari potongan yang tersimpan pada transaksi','promotion')}</div><div class="grid-two"><section class="card">${cardHead('Kontribusi member','Kinerja pelanggan yang bisa diidentifikasi')}<div class="card-pad">${bars([['Member',memberNet,compact(memberNet)],['Non-member',m.net-memberNet,compact(m.net-memberNet),'faint']])}<ul class="key-values"><li><span>Member bertransaksi</span><strong>${count(Math.round(m.baskets*.31))}</strong></li><li><span>Member belanja ulang</span><strong>${count(Math.round(m.baskets*.17))}</strong></li><li><span>Voucher masih beredar</span><strong>${compact(m.net*.012)}</strong></li></ul><p class="plain-note" style="margin-top:1rem">Voucher beredar adalah kewajiban, bukan tambahan pendapatan. Retensi memerlukan cohort dan jendela waktu yang sama.</p></div></section><section class="card">${cardHead('Baca promo dengan konteks','Dampak margin lebih penting daripada ramai transaksi')}<div class="card-pad"><p class="large-caption">${compact(discount)}</p><p class="plain-note" style="margin-top:.375rem">diskon diberikan pada ${compact(promoSales)} penjualan yang memakai promo.</p><div class="section-note">Penjualan saat promo tidak membuktikan penjualan tambahan. Incremental lift dan ROI tidak ditampilkan sampai tersedia baseline atau kelompok pembanding yang layak.</div><button class="text-link" data-metric="promotion">Definisi kontribusi promo ${icon('arrow')}</button></div></section></div><section class="card">${cardHead('Agenda Commercial & Marketing','Contoh prioritas untuk periode terpilih')}<div class="card-pad"><ul class="key-values"><li><span>Evaluasi diskon terhadap margin barang</span>${pill('Tinjau margin','warn')}</li><li><span>Hubungkan stok >90 hari ke rencana markdown</span>${navLink('inventory','Lihat barang')}</li><li><span>Pastikan penukaran voucher masuk pembukuan</span>${navLink('finance','Lihat kas & laba')}</li></ul></div></section>`;}
function people(m){const vacancies=sum(m.rows,'vacancies'),repairs=sum(m.rows,'repairs'),payroll=Math.round(m.staff*4350000);return `<div class="kpi-grid">${kpi('Karyawan aktif',count(m.staff),`${m.rows.length} toko pada akhir periode`,'people')}${kpi('Kehadiran',percent(m.attendance),'Hari hadir / hari kerja yang dijadwalkan','attendance')}${kpi('Kebutuhan personel',count(vacancies)+' posisi','Selisih rencana staffing dan penugasan aktif','people')}${kpi('Perbaikan terbuka',count(repairs),'Aset & fasilitas pada toko terpilih','assets')}</div><div class="grid-two"><section class="card">${cardHead('Kapasitas & biaya tim','Data HR agregat tanpa informasi pribadi')}<div class="card-pad"><ul class="key-values"><li><span>Estimasi payroll periode</span><strong>${compact(payroll)}</strong></li><li><span>Penjualan / karyawan aktif</span><strong>${compact(m.net/m.staff)}</strong></li><li><span>Hari hadir terhadap jadwal</span><strong>${percent(m.attendance)}</strong></li><li><span>Posisi perlu diisi</span>${pill(`${vacancies} posisi`,vacancies?'warn':'ok')}</li></ul><div class="section-note">Produktivitas ini indikator kapasitas toko. Bandingkan bersama jam kerja, format toko, dan musim penjualan; bukan penilaian kinerja individu.</div></div></section><section class="card">${cardHead('Kesiapan aset & fasilitas','Pengeluaran terkait tetap tercermin di Finance')}<div class="card-pad"><ul class="key-values"><li><span>Perbaikan terbuka</span><strong>${repairs} pekerjaan</strong></li><li><span>Anggaran perbaikan disetujui</span><strong>${compact(repairs*2250000)}</strong></li><li><span>Kontrak berakhir ≤30 hari</span>${pill(`${Math.max(1,Math.round(m.rows.length/3))} kontrak`,'warn')}</li><li><span>Inspeksi terjadwal</span><strong>${m.rows.length*2} lokasi / aset</strong></li></ul><p class="plain-note" style="margin-top:1rem">Anggaran perbaikan bukan realisasi biaya. Realisasi berasal dari tagihan yang ditautkan ke repair atau kontrak.</p><button class="text-link" data-metric="assets" style="margin-top:.75rem">Lihat hubungan data ${icon('arrow')}</button></div></section></div><section class="card">${cardHead('Kesiapan tiap toko','Karyawan, kehadiran, dan pekerjaan terbuka')}<div class="table-scroll"><table><thead><tr><th>Toko</th><th class="num">Karyawan aktif</th><th class="num">Kehadiran</th><th class="num">Posisi dibutuhkan</th><th class="num">Perbaikan terbuka</th></tr></thead><tbody>${m.rows.map(r=>`<tr><td><strong>${r.name}</strong></td><td class="num">${r.staff}</td><td class="num ${r.attendance<95?'warning':''}">${percent(r.attendance)}</td><td class="num">${r.vacancies||'—'}</td><td class="num">${r.repairs}</td></tr>`).join('')}</tbody></table></div></section>`;}
const definitions={
 sales:{title:'Penjualan bersih operasional',formula:'Penjualan barang setelah diskon − retur barang, tidak termasuk pajak dan biaya layanan.',sources:['sale','sale_line','edge_sale','edge_sale_line','sale_return','sale_return_line'],body:'Gabungkan transaksi pusat dan transaksi edge yang sudah selesai. Gunakan identitas sumber + ID transaksi. Abaikan void dan open; normalisasi retur pada basis sebelum pajak. Nilai biaya layanan tidak ikut menjadi penjualan barang.',limit:'Adapter laporan saat ini perlu diaudit lagi: sebagian pembaca lama belum memfilter edge_sale.status dan belum menyelaraskan retur edge, pajak, serta biaya layanan. Jangan langsung menjadikan SUM(total_minor) sebagai KPI ini.'},
 margin:{title:'Laba kotor dagang & margin',formula:'Laba kotor = penjualan bersih barang − biaya barang yang benar-benar terjual. Margin = laba kotor ÷ penjualan bersih × 100%.',sources:['stock_ledger_entry','cost_layer','inventory_cost_flag','sale_line','edge_sale_line'],body:'Biaya diatribusikan pada unit yang terjual dan lapisan biaya yang relevan. Margin gabungan adalah rasio total laba terhadap total penjualan, bukan rata-rata persentase setiap toko.',limit:'Tidak tersedia cost layer pada database yang diperiksa. Tampilkan “belum tersedia” di versi live sampai coverage biaya cukup; jangan menganggap biaya yang hilang sebagai nol.'},
 stock:{title:'Stok toko & nilai persediaan',formula:'Unit pada posisi on-hand yang dimiliki toko × biaya perolehan lapisan yang masih tersedia.',sources:['movement','inventory_projection','edge_inventory_fact_position','operational_pool','inventory_place','cost_layer_remaining','stock_ledger_entry'],body:'Gunakan satu authority per node. Posisi edge berasal dari fakta edge, dengan snapshot sebagai checkpoint. Stok DC, barang dalam perjalanan, missing, dan lost memiliki kategori terpisah. Nilai persediaan memakai biaya, bukan harga jual.',limit:'Database berisi posisi native dan edge, tetapi cost_layer serta stock_ledger_entry kosong. Skema kuantitas tersedia; valuasi lengkap belum bisa dibuktikan.'},
 aging:{title:'Umur persediaan',formula:'Tanggal snapshot − economic_date lapisan penerimaan untuk unit yang masih tersedia.',sources:['cost_layer','cost_layer_remaining','goods_receipt_line','stock_ledger_entry'],body:'Kelompokkan 0–30, 31–60, 61–90, dan >90 hari. Perpindahan antar-rak atau antar-pool tidak mengubah umur barang. Unit tanpa atribusi penerimaan masuk kelompok “umur belum diketahui”.',limit:'Lapisan biaya dan penerimaan kosong di dataset lokal. Semua distribusi umur pada prototipe adalah simulasi.'},
 cover:{title:'Cakupan stok',formula:'Unit tersedia di akhir periode ÷ (unit terjual bersih selama periode ÷ jumlah hari periode).',sources:['edge_inventory_fact_position','inventory_projection','sale_line','edge_sale_line','sale_return_line'],body:'Pembilang dan penyebut memakai toko serta komposisi barang yang sama. Jika laju jual nol, hasil ditampilkan “tidak ada penjualan”, bukan tak hingga atau nol hari.',limit:'Snapshot akhir historis harus direkonstruksi dari ledger. Jangan memakai stok hari ini untuk laporan bulan lalu.'},
 basket:{title:'Transaksi, rata-rata struk & unit per transaksi',formula:'Rata-rata struk = penjualan bersih ÷ struk selesai. UPT = unit terjual ÷ struk selesai.',sources:['sale','edge_sale','sale_line','edge_sale_line'],body:'Satu struk dihitung sekali walaupun memiliki banyak item, tender, atau promosi. Penggabungan tabel anak perlu diagregasikan dulu agar jumlah struk dan uang tidak berlipat.',limit:'Sepakati apakah unit pada UPT termasuk pengurangan retur di periode yang sama, lalu gunakan definisi itu konsisten di semua halaman.'},
 comparison:{title:'Perbandingan periode',formula:'Perubahan = (nilai periode ini ÷ nilai periode pembanding − 1) × 100%.',sources:['site','sale','edge_sale','sync_ingest_watermark','sync_applied_watermark'],body:'01–25 September dibanding 01–25 Agustus; Agustus penuh dibanding Juli penuh. Batas hari memakai WIB, dengan rentang awal inklusif dan akhir eksklusif. Perbandingan kalender ini belum disesuaikan jumlah akhir pekan.',limit:'Jika basis nol, tampilkan “baru / basis nol”. Toko baru, tutup, atau belum sinkron harus diberi status. Same-store growth butuh cohort eksplisit dan bukan angka default prototipe ini.'},
 cash:{title:'Kas & bank',formula:'Saldo debit − kredit pada akun kas/bank sampai tanggal akhir periode, sesuai normal balance dan saldo pembukaan.',sources:['journal_entry','journal_line','ledger_account','bank_account','bank_statement','bank_line_match','cash_count'],body:'Saldo buku dipisahkan dari saldo bank dan hasil hitung kas. Saldo akhir harus mencakup seluruh jurnal historis sampai cutoff, termasuk saldo pembukaan dan reversal.',limit:'Bank statement dan rekening perusahaan belum terisi pada dataset ini. Kas buku tidak sama dengan dana bebas; giro beredar dan dana terikat perlu disajikan terpisah.'},
 profit:{title:'Laba menurut buku',formula:'Pendapatan − HPP − beban usaha − beban usaha lainnya + nonoperasi − pajak penghasilan.',sources:['journal_entry','journal_line','ledger_account','fiscal_period','sales_posting'],body:'Ikuti statement_section akun, bukan awalan kode. journal_entry adalah jurnal tercatat; reversal tetap ikut dengan tanda ekonominya. Gunakan lapisan P&L yang sudah ada di backend: gross profit → gross operating profit → net operating profit → before tax → net profit.',limit:'Angka per toko belum memasukkan overhead HO atau eliminasi antarunit. Jangan menyebutnya laba konsolidasi. Migrasi 0379 untuk lapisan laba terbaru ada di source, sementara database yang dibaca baru sampai 0378.'},
 payables:{title:'Utang & jatuh tempo',formula:'Saldo terutang yang belum dialokasikan, dikelompokkan menurut tanggal jatuh tempo tiap termin.',sources:['payment_ledger_entry','payment_ledger_settlement','supplier_invoice','supplier_invoice_payment_term','supplier_invoice_standing'],body:'Gunakan outstanding setelah settlement, bukan nilai faktur asli. Abaikan entry yang delinked. Jadwal termin mencegah seluruh faktur dianggap jatuh tempo pada tanggal termin pertama.',limit:'Tagihan tanpa due date masuk “jatuh tempo belum ditetapkan”, bukan terlambat. Hari cutoff laporan tidak boleh diganti current_date untuk laporan historis. Database lokal belum punya saldo AP bisnis.'},
 purchase:{title:'Komitmen pembelian',formula:'Nilai baris PO yang telah diterbitkan dan belum diterima / dibatalkan, sesudah perubahan harga yang disepakati.',sources:['purchase_order','purchase_order_line','purchase_price_amendment','goods_receipt','goods_receipt_line','allotment_line_commitment'],body:'Pisahkan komitmen pemesanan, penerimaan, dan distribusi ke toko. PO menuju DC tidak otomatis menjadi komitmen satu toko sebelum ada alokasi yang menghubungkannya.',limit:'Untuk filter satu toko, PO tanpa alokasi toko harus tampil sebagai “HO/DC, belum dialokasikan”. Fixture UI menunjukkan skenario yang sudah dialokasikan; tabel PO dan receipt pada database audit masih kosong.'},
 members:{title:'Kontribusi member',formula:'Penjualan bersih dengan identitas member ÷ seluruh penjualan bersih pada scope dan periode yang sama.',sources:['member','sale','edge_sale','points_ledger','voucher','voucher_movement'],body:'Identitas member ditautkan lewat customer_id yang sah, bukan menebak dari nama pelanggan. Agregat tidak perlu menampilkan telepon, identitas, atau data personal.',limit:'Belanja ulang butuh histori transaksi; cohort retensi perlu definisi jendela. Database demo hanya mempunyai satu member, sehingga belum representatif untuk analisis bisnis.'},
 promotion:{title:'Penjualan berpromo & diskon',formula:'Penjualan yang menggunakan promo, dengan atribusi potongan tersimpan pada line transaksi; bukan estimasi kenaikan akibat promo.',sources:['commercial_campaign','commercial_rule','edge_sale_promotion','edge_sale_promotion_line','commercial_usage','campaign_activity'],body:'Gunakan snapshot promo pada waktu transaksi, bukan rule promo saat ini. Promo bertumpuk bisa mempunyai beberapa baris atribusi; agregat “penjualan berpromo” harus tetap menghitung satu transaksi sekali.',limit:'Incremental lift, ROMI, dan dampak kausal memerlukan baseline / pembanding serta biaya kampanye. Tidak ada tabel footfall untuk menghitung conversion pengunjung ke pembeli.'},
 people:{title:'Headcount & kebutuhan personel',formula:'Karyawan aktif dengan penugasan yang berlaku pada cutoff; kebutuhan = staffing plan − kapasitas terisi.',sources:['employee','employee_assignment','employee_contract','staffing_plan','org_place','payroll_run','payroll_slip'],body:'Hubungkan tempat HR ke site melalui pemetaan yang sah. Hitung penugasan yang berlaku saat tanggal laporan, bukan status terkini untuk semua bulan. Gunakan hasil payroll final yang sesuai periode untuk biaya.',limit:'Tabel employee, assignment, payroll, dan staffing_plan kosong di database yang diperiksa. Rencana staffing tidak otomatis berarti ada lowongan rekrutmen yang sudah disetujui.'},
 attendance:{title:'Kehadiran terhadap jadwal',formula:'Hari kerja hadir yang tervalidasi ÷ hari kerja yang dijadwalkan pada periode yang sama.',sources:['roster_day','attendance_punch','attendance_correction','leave_request','holiday_calendar','attendance_period'],body:'Baca roster, cuti resmi, hari libur, punch, dan koreksi terbaru yang disetujui. Raw punch bukan jumlah hari hadir. Headcount-weighted percentage di fixture hanya skenario untuk menguji tampilan.',limit:'Kebijakan denominator harus disepakati untuk cuti dan penugasan lintas toko. Tampilkan coverage roster/punch sebelum memberi status kehadiran.'},
 assets:{title:'Kesiapan aset & fasilitas',formula:'Pekerjaan terbuka pada cutoff, kontrak akan berakhir, dan biaya yang terkait dokumen GA.',sources:['fixed_asset','ga_repair','ga_maintenance_task','ga_contract','ga_inspection','supplier_invoice_expense_line'],body:'Realisasi pengeluaran ditelusuri melalui tagihan yang menunjuk repair_id, contract_id, atau replacement_id. Nilai anggaran, nilai tagihan, dan nilai yang dibayar adalah tiga hal berbeda.',limit:'Aset register belum tentu memiliki valuasi atau kapitalisasi. Lima aset sudah ada di database ini; repair, kontrak, dan inspeksi masih kosong.'},
 reconciliation:{title:'Penjualan operasional vs pembukuan',formula:'Penjualan bersih operasional − pendapatan penjualan yang telah dibukukan untuk transaksi dan periode yang cocok.',sources:['sales_posting','sales_posting_exception','sale_day_posting','journal_entry','journal_line','edge_sale'],body:'Gunakan penjualan yang sama dan telusuri posting authority yang berlaku. Pisahkan belum diposting, beda tanggal, koreksi, reversal, pajak, fee, dan retur. Jangan menjumlahkan jalur posting lama dan baru sebagai dua penjualan.',limit:'Completeness tidak cukup ditentukan oleh jumlah dokumen posting. Laporan final memerlukan coverage transaksi, sinkronisasi, dan rekonsiliasi GL.'}
};
const audit=window.EXECUTIVE_AUDIT||{summary:{},tables:[],database:'Tidak termuat'};
function coverage(){const s=audit.summary;return `<section class="card coverage-banner">${icon('database')}<div><strong>Seluruh skema public sudah dipetakan</strong><p>Database lokal <code>${esc(audit.database)}</code> · 25 September 2026 · pemeriksaan read-only.</p></div><a href="database-inventory.json" download class="button">Unduh inventaris</a></section><div class="kpi-grid">${kpi('Tabel & view',`${s.base_tables||'—'} + ${s.views||'—'}`,'Seluruh relasi dalam skema public','audit')}${kpi('Kolom',count(s.columns||0),'Nama, tipe, nullable; tanpa isi data pribadi','audit')}${kpi('Relasi foreign key',count(s.foreign_keys||0),'Pemetaan hubungan antar-tabel','audit')}${kpi('Tabel / view terisi',`${s.populated||'—'} / ${s.relations||'—'}`,`${s.empty||'—'} masih kosong di dataset ini`,'audit')}</div><div class="grid-two"><section class="card">${cardHead('Kesiapan sumber bisnis','Terisi belum berarti lengkap atau terverifikasi')}<div class="card-pad"><ul class="key-values">${[['Penjualan edge','edge_sale','26 transaksi · parsial'],['Jurnal tercatat','journal_entry','7 jurnal · parsial'],['Lapisan biaya','cost_layer','Kosong'],['Tagihan pemasok','supplier_invoice','Kosong'],['Karyawan','employee','Kosong'],['Aset terdaftar','fixed_asset','5 aset · parsial']].map(([n,t])=>{const c=audit.tables.find(x=>x.name===t)?.rows||0;return `<li><span>${n}</span>${pill(c?`${count(c)} baris · parsial`:'Belum ada data',c?'info':'')}</li>`;}).join('')}</ul></div></section><section class="card">${cardHead('Batas rancangan','Hal yang perlu selesai sebelum report menjadi live')}<div class="card-pad plain-note"><p>UI bisnis menggunakan <strong>simulasi</strong>. Inventaris di halaman ini adalah hasil pembacaan database lokal sesungguhnya.</p><div class="section-note">Belum ada endpoint Executive Report, snapshot laporan, atau proses publikasi final. Saved Reports yang ada menyimpan definisi query dan menjalankannya pada data terkini.</div><p>Database audit sampai migrasi <strong>${s.latest_migration}</strong>. Source memiliki perubahan yang lebih baru, termasuk format laba dan divisi. Perlu menyamakan versi sebelum implementasi.</p><button class="text-link" data-action="definitions" style="margin-top:1rem">Buka seluruh definisi metrik ${icon('arrow')}</button></div></section></div><section class="card">${cardHead('Inventaris seluruh tabel & view','Jumlah baris dihitung pada database lokal; klik nama untuk metadata.')}<div class="table-toolbar"><label class="search">${icon('search')}<input id="db-search" type="search" placeholder="Cari nama tabel…" aria-label="Cari tabel" value="${esc(state.dbSearch)}"></label><select id="db-filter" class="dataset-filter" aria-label="Filter isi database"><option value="all">Semua tabel / view</option><option value="filled">Terisi</option><option value="empty">Kosong</option><option value="view">Hanya view</option></select></div><div class="table-scroll"><table><thead><tr><th>Nama</th><th>Tipe</th><th class="num">Baris</th><th class="num">Kolom</th><th class="num">Foreign key</th><th>Cakupan</th></tr></thead><tbody id="db-body">${dbRows()}</tbody></table></div><div class="table-foot"><span id="db-count"></span><span>Tanpa query isi kredensial, biometrik, atau data pribadi.</span></div></section>`;}
function dbSelection(){return audit.tables.filter(t=>t.name.includes(state.dbSearch.toLowerCase())&&(state.dbFilter==='all'||state.dbFilter==='filled'&&t.rows>0||state.dbFilter==='empty'&&t.rows===0||state.dbFilter==='view'&&t.kind==='VIEW'));}
function dbRows(){const rows=dbSelection();return rows.length?rows.map(t=>`<tr data-table="${esc(t.name)}"><td><button class="row-title mono" data-table="${esc(t.name)}">${esc(t.name)}</button></td><td>${t.kind==='VIEW'?'View':'Table'}</td><td class="num">${count(t.rows)}</td><td class="num">${t.columns}</td><td class="num">${t.relationships}</td><td><span class="data-status ${t.rows?'':'empty-data'}"><i></i>${t.rows?'Terisi':'Kosong'}</span></td></tr>`).join(''):`<tr><td colspan="6" class="empty">Tidak ada tabel yang cocok dengan pencarian ini.</td></tr>`;}
function updateDb(){document.querySelector('#db-body').innerHTML=dbRows();document.querySelector('#db-count').textContent=`${dbSelection().length} dari ${audit.tables.length} tabel / view`;}
function saved(){return `<section class="card">${cardHead('Contoh laporan','Tautan demo untuk menguji alur masuk dari pustaka.',pill('Contoh'))}<a class="archive-row" href="#overview?period=sep&scope=all">${icon('report')}<div><h3>Executive Report · September 2026</h3><p>01–25 September · semua toko · bulan berjalan</p></div>${pill('Preview','info')}${icon('chevron')}</a><a class="archive-row" href="#overview?period=aug&scope=all">${icon('report')}<div><h3>Executive Report · Agustus 2026</h3><p>Bulan penuh · semua toko · data simulasi</p></div>${pill('Simulasi')}${icon('chevron')}</a><a class="archive-row" href="#stores?period=sep&scope=store-07">${icon('store')}<div><h3>Kinerja Store 07</h3><p>Penjualan, margin, dan stok · September 2026</p></div>${pill('Sudut pandang')}${icon('chevron')}</a></section><div class="section-note">Prototipe ini belum menyimpan atau menerbitkan laporan. Dalam rancangan live, “laporan final” memerlukan snapshot angka, versi definisi, cutoff data, dan status pemeriksaan. Saved Reports yang sekarang tetap berfungsi sebagai pustaka definisi laporan dinamis.</div>`;}
function readHash(){const [page,query]=location.hash.replace(/^#/,'').split('?');state.page=Object.hasOwn(pages,page)?page:'overview';const params=new URLSearchParams(query||'');if(['sep','aug'].includes(params.get('period')))state.period=params.get('period');if(params.get('scope')==='all'||baseStores.some(s=>s.id===params.get('scope')))state.scope=params.get('scope');if(params.has('compare'))state.compare=params.get('compare')!=='0';}
function persistHash(){history.replaceState(null,'',`#${state.page}?period=${state.period}&scope=${state.scope}&compare=${state.compare?1:0}`);}
function render(){const [title,sub]=pages[state.page],m=model(),business=!['coverage','saved','reference'].includes(state.page);document.title=`${title} · ${state.page==='reference'?actual.company:'Wira Makmur'}`;document.querySelector('#definition-button').textContent=state.page==='reference'?'Sumber & definisi':'Definisi metrik';document.querySelector('#page-title').textContent=title;document.querySelector('#page-sub').textContent=sub;document.querySelector('#breadcrumb').textContent=title;document.querySelector('#period').value=state.period;document.querySelector('#scope').value=state.scope;document.querySelector('#compare').checked=state.compare;document.querySelector('#filterbar').hidden=!business;document.querySelector('#context-line').hidden=!business;document.querySelector('#print-button').hidden=!business&&state.page!=='reference';document.querySelector('#period-state').innerHTML=icon('clock')+(state.period==='sep'?'Bulan berjalan':'Bulan penuh');document.querySelector('#context-line').innerHTML=`<span>${periodLabel()} · ${scopeLabel()} · WIB${state.compare?' · dibanding '+beforeLabel():''}</span><span>Data simulasi <span aria-hidden="true">·</span> <button data-action="coverage">Cek sumber & cakupan</button></span>`;document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===state.page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('#view').innerHTML=({overview,stores,inventory,finance,customers,people,coverage,saved,reference}[state.page])(m);if(document.querySelector('#store-body'))updateStoreTable();syncNav();if(document.querySelector('#db-body')){document.querySelector('#db-filter').value=state.dbFilter;updateDb();}decorateTables();document.querySelector('#footer-note').textContent=business?'Angka simulasi untuk evaluasi desain · IDR · WIB':state.page==='reference'?'Angka dari dokumen Finance · 2025 / 2024 · kompilasi unit, belum konsolidasi':state.page==='coverage'?'Inventaris lokal 25 Sep 2026 · read-only · tanpa data baris pribadi':'Contoh pustaka · belum terhubung ke penyimpanan';persistHash();}
function openDetail(title,body,kicker='DEFINISI METRIK'){document.querySelector('#detail-title').textContent=title;document.querySelector('#detail-kicker').textContent=kicker;document.querySelector('#detail-body').innerHTML=body;const d=document.querySelector('#detail');if(!d.open)d.showModal();document.querySelector('#detail-body').scrollTop=0;}
function openMetric(key){if(key.startsWith('actual-')){openFinanceSource(key.slice(7));return;}if(key==='audit'){openDetail('Pemeriksaan seluruh database',`<p>Inventaris meliputi seluruh ${audit.summary.relations} tabel/view pada skema public di <code>${esc(audit.database)}</code>. Query dijalankan dalam transaksi READ ONLY dengan timeout, tanpa mutasi.</p><p>Yang dibaca: nama dan tipe kolom, nullable, foreign key, serta jumlah baris exact. Isi data pribadi, kredensial, dan biometrik tidak disalin ke prototipe.</p><p>Beberapa batch metadata dijalankan berurutan, jadi inventaris ini adalah pemeriksaan pada waktu pengambilan, bukan snapshot keuangan yang dibekukan.</p><a class="button" href="database-inventory.json" download>Unduh metadata lengkap</a>`,'CAKUPAN PEMERIKSAAN');return;}const d=definitions[key];if(!d)return;openDetail(d.title,`<div class="formula">${d.formula}</div><h3>Cara membaca</h3><p>${d.body}</p><h3>Sumber</h3><div class="source-tags">${d.sources.map(s=>`<code>${s}</code>`).join('')}</div><h3>Batas data & implementasi</h3><p>${d.limit}</p><div class="section-note">Angka pada tampilan bisnis prototipe adalah simulasi, tidak dihitung dari database audit.</div>`);}
function openDefinitions(){openDetail('Kamus angka Executive Report',`<p>Definisi, source of truth, dan batas kesiapan data untuk setiap angka yang dipakai.</p><ul class="key-values">${Object.entries(definitions).map(([k,d])=>`<li><button class="text-link" data-metric="${k}">${d.title}${icon('chevron')}</button></li>`).join('')}</ul>`,'PANDUAN MEMBACA');}
function openStore(id){const m=model(),s=m.rows.find(r=>r.id===id);if(!s)return;openDetail(s.name,`<p>${periodLabel()} · angka simulasi</p><div class="kpi-grid" style="grid-template-columns:1fr 1fr">${kpi('Penjualan bersih',compact(s.net),delta((s.net/s.prior-1)*100),'sales')}${kpi('Margin kotor',percent(s.margin),compact(s.net-s.cogs)+' laba kotor','margin')}</div><ul class="key-values"><li><span>Transaksi</span><strong>${count(s.baskets)}</strong></li><li><span>Unit terjual</span><strong>${count(s.units)}</strong></li><li><span>Rata-rata struk</span><strong>${money(s.net/s.baskets)}</strong></li><li><span>Unit tersedia</span><strong>${count(s.stock)}</strong></li><li><span>Cakupan stok</span><strong>${count(s.stock/(s.units/m.days))} hari</strong></li></ul><h3>Fokus pembahasan</h3><p>${s.net<s.prior?'Telusuri penurunan per artikel, ukuran, dan jam transaksi. Cek juga kelengkapan data serta ketersediaan barang.':'Pertumbuhan positif. Jaga ketersediaan ukuran utama dan pantau keseimbangan stok dengan laju penjualan.'}</p><button class="button" data-focus-store="${id}">Gunakan toko ini untuk seluruh laporan ${icon('arrow')}</button>`,'KINERJA TOKO');}
let toastTimer;
function toast(text){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),4000);}
document.addEventListener('click',e=>{
 const metric=e.target.closest('[data-metric]');if(metric){openMetric(metric.dataset.metric);return;}
 const store=e.target.closest('[data-store]');if(store){openStore(store.dataset.store);return;}
 const table=e.target.closest('[data-table]');if(table){const t=audit.tables.find(t=>t.name===table.dataset.table);const related=Object.entries(definitions).filter(([,d])=>d.sources.includes(t.name));openDetail(t.name,`<p>Metadata database lokal, bukan simulasi.</p><ul class="key-values"><li><span>Tipe</span><strong>${t.kind}</strong></li><li><span>Baris</span><strong>${count(t.rows)}</strong></li><li><span>Kolom</span><strong>${t.columns}</strong></li><li><span>Foreign key keluar</span><strong>${t.relationships}</strong></li></ul><h3>Dipakai oleh metrik</h3>${related.length?related.map(([k,d])=>`<p><button class="text-link" data-metric="${k}">${d.title}${icon('arrow')}</button></p>`).join(''):'<p>Tabel pendukung aplikasi. Tidak menjadi sumber langsung KPI pada rancangan ini.</p>'}<p>${t.rows?'Adanya baris belum memastikan kelengkapan seluruh periode atau toko.':'Tabel ini masih kosong pada dataset yang diperiksa.'}</p><a class="button" href="database-inventory.json" download>Unduh kolom & relasi lengkap</a>`,'INVENTARIS DATABASE');return;}
 const filter=e.target.closest('[data-store-filter]');if(filter){state.storeFilter=filter.dataset.storeFilter;updateStoreTable();return;}
 const sort=e.target.closest('[data-sort]');if(sort){if(state.sort===sort.dataset.sort)state.descending=!state.descending;else{state.sort=sort.dataset.sort;state.descending=true;}updateStoreTable();return;}
 const focus=e.target.closest('[data-focus-store]');if(focus){state.scope=focus.dataset.focusStore;document.querySelector('#detail').close();render();return;}
 const shell=e.target.closest('[data-shell]');if(shell){toast(`${shell.dataset.shell} adalah konteks aplikasi. Prototipe ini berfokus pada menu Reports.`);return;}
 const financeSource=e.target.closest('[data-finance-source]');if(financeSource){openFinanceSource(financeSource.dataset.financeSource);return;}
 const act=e.target.closest('[data-action]')?.dataset.action;
 if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#content').focus();document.querySelector('#content').scrollIntoView();return;}
 if(act==='navigation'){if(matchMedia('(max-width:1023px)').matches)document.body.classList.toggle('nav-open');else document.body.classList.toggle('sidebar-hidden');syncNav();}
 if(act==='close-detail')document.querySelector('#detail').close();
 if(act==='definitions'){if(state.page==='reference')openFinanceSource('documents');else openDefinitions();}
 if(act==='coverage')location.hash='coverage';
 if(act==='print')window.print();
 if(act==='help')openDetail('Prototype Executive Report',`<p>HTML/CSS dengan JavaScript ringan untuk menguji interaksi. Mengikuti rail, sidebar, tipografi, warna, dan radius frontend-hub per 25 September 2026.</p><p>Halaman Ringkasan Finance 2025 memakai angka dari dokumen yang diberikan. Halaman operasional 2026 memakai simulasi. Cakupan data berisi inventaris database lokal yang benar-benar diperiksa.</p><h3>Yang dapat dicoba</h3><ul><li>Berpindah bagian laporan.</li><li>Mengganti periode dan cakupan toko.</li><li>Mencari, mengurutkan, dan menelusuri toko.</li><li>Membuka definisi setiap KPI.</li><li>Mencari seluruh tabel database.</li><li>Mencetak bagian yang sedang dibuka.</li></ul><p>Belum ada koneksi live, simpan, persetujuan, atau publikasi report.</p>`,'TENTANG PROTOTIPE');
});
document.querySelector('#period').addEventListener('change',e=>{state.period=e.target.value;render();});document.querySelector('#scope').addEventListener('change',e=>{state.scope=e.target.value;state.search='';render();});document.querySelector('#compare').addEventListener('change',e=>{state.compare=e.target.checked;render();});
document.addEventListener('input',e=>{if(e.target.id==='store-search'){state.search=e.target.value;updateStoreTable();}if(e.target.id==='db-search'){state.dbSearch=e.target.value;updateDb();}});
document.addEventListener('change',e=>{if(e.target.id==='db-filter'){state.dbFilter=e.target.value;updateDb();}});
window.addEventListener('hashchange',()=>{readHash();document.body.classList.remove('nav-open');document.querySelector('#detail').close();render();window.scrollTo(0,0);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('nav-open');syncNav();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='b'){e.preventDefault();document.querySelector('#nav-toggle').click();}});
function decorateTables(){document.querySelectorAll('#view table').forEach(table=>{if(table.querySelector('#db-body'))return;const labels=[...table.querySelectorAll('th')].map(n=>n.textContent.trim());const tbody=table.querySelector('tbody');if(!tbody)return;if(tbody.id!=='store-body')tbody.classList.add('business-rows');tbody.querySelectorAll('tr').forEach(row=>[...row.children].forEach((cell,i)=>cell.dataset.label=labels[i]||''));});}
function syncNav(){const mobile=matchMedia('(max-width:1023px)').matches,opened=document.body.classList.contains('nav-open');const fold=document.querySelector('.fold');fold.setAttribute('aria-pressed',!document.body.classList.contains('sidebar-hidden'));fold.setAttribute('aria-label',document.body.classList.contains('sidebar-hidden')?'Buka sidebar':'Lipat sidebar');for(const el of [document.querySelector('#rail'),document.querySelector('#sidebar')])el.inert=mobile&&!opened;document.querySelector('.workspace-main').inert=mobile&&opened;document.querySelector('#nav-toggle').setAttribute('aria-expanded',mobile?opened:!document.body.classList.contains('sidebar-hidden'));}
window.addEventListener('resize',syncNav);
matchMedia('(max-width:1023px)').addEventListener('change',syncNav);

// Annual finance reference is independent of the simulated 2026 store filters.
const actual = window.FINANCE_REFERENCE;
const precisePercent = n => n.toLocaleString('id-ID', {minimumFractionDigits:2, maximumFractionDigits:2})+'%';
const actualChange = (a,b) => (a/b-1)*100;
const signedMoney = n => (n>0?'+':n<0?'−':'')+compact(Math.abs(n));
function actualDelta(item, expense=false) {
 const n=actualChange(item.current,item.prior);
 return `<span class="delta ${(expense?n<=0:n>=0)?'positive':'negative'}">${n>=0?'↑':'↓'} ${precisePercent(Math.abs(n))}</span> vs 2024`;
}
function reference() {
 const p=actual.pl, d=actual.divisionTotals;
 const expenses={current:p.opex.current+p.otherOpex.current,prior:p.opex.prior+p.otherOpex.prior};
 const netMargin=p.profit.current/p.sales.current*100, grossMargin=p.gross.current/p.sales.current*100;
 const effects=[['Laba kotor',p.gross.current-p.gross.prior],['Beban usaha',-(p.opex.current-p.opex.prior)],['Beban usaha lainnya',-(p.otherOpex.current-p.otherOpex.prior)],['Nonoperasi',p.nonOperating.current-p.nonOperating.prior],['Pajak',-(p.tax.current-p.tax.prior)]];
 const maxEffect=Math.max(...effects.map(([,n])=>Math.abs(n)));
 const rows=Object.entries(p).map(([key,r])=>`<tr class="${['gross','profit','netOperating'].includes(key)?'statement-total':''}"><td><button class="row-title" data-finance-source="${key}">${r.label}</button></td><td class="num">${compact(r.current)}</td><td class="num">${compact(r.prior)}</td><td class="num">${signedMoney(r.current-r.prior)}</td></tr>`).join('');
 const divisions=[...actual.divisions].sort((a,b)=>b.net-a.net);
 const reconcile=[['Penjualan bersih',d.net,p.sales.current],['HPP',d.cost,p.cogs.current],['Laba kotor',d.grossProfit,p.gross.current]];
 return `<div class="source-context"><span>${icon('report')} Dokumen Finance · Januari–Desember 2025 / 2024 · IDR</span>${pill('Angka dari workbook','info')}<button class="text-link" data-finance-source="documents">5 dokumen sumber ${icon('arrow')}</button></div>
 <section class="card brief"><span class="brief-mark">${icon('chart')}</span><div><div class="eyebrow">INTI KINERJA TAHUNAN</div><h2>Penjualan turun 2,12%; tekanan biaya memperbesar penurunan laba.</h2><p>Laba setelah pajak turun <strong>${compact(p.profit.prior-p.profit.current)}</strong>. Margin kotor terhadap penjualan bersih naik tipis menjadi <strong>${precisePercent(grossMargin)}</strong>, sementara total beban usaha naik <strong>${precisePercent(actualChange(expenses.current,expenses.prior))}</strong>. Fokus pembahasan: kerusakan persediaan, biaya toko, dan kelengkapan HPP.</p></div>${pill('Kompilasi unit')}</section>
 <div class="kpi-grid">${kpi('Penjualan bersih',compact(p.sales.current),actualDelta(p.sales),'actual-sales')}${kpi('Laba kotor',compact(p.gross.current),`${precisePercent(grossMargin)} dari penjualan bersih`,'actual-gross')}${kpi('Laba setelah pajak',compact(p.profit.current),actualDelta(p.profit),'actual-profit')}${kpi('Total beban usaha',compact(expenses.current),actualDelta(expenses,true),'actual-expenses')}</div>
 <div class="grid-two"><section class="card">${cardHead('Apa yang mengurangi laba?','Dampak perubahan komponen terhadap laba setelah pajak')}<div class="card-pad"><div class="profit-comparison"><div><small>2024</small><strong>${compact(p.profit.prior)}</strong></div>${icon('arrow')}<div><small>2025</small><strong>${compact(p.profit.current)}</strong></div><span class="pill bad">−27,19%</span></div><div class="profit-effects">${effects.map(([label,n])=>`<div class="effect-row"><span>${label}</span><div class="effect-track"><i class="${n>=0?'gain':'loss'}" style="width:${Math.max(1.5,Math.abs(n)/maxEffect*100)}%"></i></div><strong class="num ${n>=0?'positive':'negative'}">${signedMoney(n)}</strong></div>`).join('')}</div><div class="effect-total"><span>Perubahan laba setelah pajak</span><strong class="negative">${signedMoney(p.profit.current-p.profit.prior)}</strong></div><p class="plain-note">Kelima perubahan menjumlah ke selisih laba. Margin bersih: ${precisePercent(p.profit.prior/p.sales.prior*100)} → <strong>${precisePercent(netMargin)}</strong>, memakai penjualan bersih sebagai pembagi.</p><button class="text-link source-link" data-finance-source="bridge">Lihat angka & sumber ${icon('arrow')}</button></div></section>
 <section class="card">${cardHead('Biaya yang perlu dibahas','Pilihan kenaikan nominal untuk ditelusuri bersama Finance')}<div class="card-pad"><ul class="cost-drivers">${actual.costDrivers.map((r,i)=>`<li><span class="driver-index">${i+1}</span><div><button class="row-title" data-finance-source="driver-${i}">${r.label}</button><p>${compact(r.prior)} → ${compact(r.current)}</p></div><strong class="num warning">+${compact(r.current-r.prior)}</strong></li>`).join('')}</ul><div class="section-note">Kerusakan persediaan naik ${compact(actual.costDrivers[0].current-actual.costDrivers[0].prior)}. Telusuri asal jurnal, kebijakan pengakuan, dan periode kejadiannya sebelum menyimpulkan penyebab bisnis.</div><p class="plain-note">Rincian ini sudah termasuk dalam beban di sebelah kiri; tidak ditambahkan lagi ke perubahan laba. Depresiasi FFE merupakan kelompok biaya.</p></div></section></div>
 <section class="card reference-section">${cardHead('Laba-rugi kompilasi unit','Nilai buku · klik nama baris untuk angka penuh dan referensi sel',pill('2025 vs 2024'))}<div class="table-scroll"><table><thead><tr><th>Komponen</th><th class="num">2025</th><th class="num">2024</th><th class="num">Perubahan nominal</th></tr></thead><tbody>${rows}</tbody></table></div><div class="table-foot"><span>Kompilasi belum membuktikan eliminasi antarunit.</span><button class="text-link" data-finance-source="margin">Basis persentase ${icon('info')}</button></div></section>
 <section class="card reference-section">${cardHead('Dari mana penjualan & margin berasal?','9 divisi · Januari–Desember 2025 · HPP rata-rata dari laporan penjualan',pill('Sumber divisi','info'))}<div class="table-scroll"><table><thead><tr><th>Divisi</th><th class="num">Penjualan bersih</th><th class="num">Kontribusi</th><th class="num">HPP rata-rata</th><th class="num">Laba kotor</th><th class="num">Margin</th></tr></thead><tbody>${divisions.map(r=>`<tr><td><button class="row-title" data-finance-source="division-${esc(r.code)}">${esc(r.name)}</button>${Number(r.code)===9?'<span class="cell-note warning">Periksa HPP</span>':''}</td><td class="num">${compact(r.net)}</td><td class="num">${precisePercent(r.net/d.net*100)}</td><td class="num">${compact(r.cost)}</td><td class="num">${compact(r.grossProfit)}</td><td class="num ${Number(r.code)===9?'warning':''}">${precisePercent(r.margin*100)}</td></tr>`).join('')}</tbody></table></div><div class="card-pad division-note"><div><strong>70,31% penjualan berasal dari Pria & Wanita.</strong><p>Kontribusi dihitung terhadap total penjualan bersih pada laporan divisi.</p></div><div><strong class="warning">Non Divisi: margin 99,99%</strong><p>Penjualan ${compact(actual.divisions[8].net)}, HPP hanya ${money(actual.divisions[8].cost)}. Verifikasi biaya dan klasifikasinya sebelum memakai margin ini sebagai indikator.</p></div></div></section>
 <section class="card reference-section">${cardHead('Rekonsiliasi sebelum dipakai bersama','Perbandingan total 2025 · laporan divisi dikurangi laba-rugi GL',pill('Ada selisih','warn'))}<div class="table-scroll"><table><thead><tr><th>Komponen</th><th class="num">Laporan divisi</th><th class="num">Laba-rugi GL</th><th class="num">Selisih</th></tr></thead><tbody>${reconcile.map(([label,a,b])=>`<tr><td><strong>${label}</strong></td><td class="num">${money(a)}</td><td class="num">${money(b)}</td><td class="num warning">${a-b>0?'+':'−'}${money(Math.abs(a-b))}</td></tr>`).join('')}</tbody></table></div><div class="card-pad"><p class="plain-note">Nilai bruto dan diskon kedua laporan juga berbeda basis penyajiannya. Di laporan divisi sendiri, bruto − diskon − retur menghasilkan nilai <strong>Rp244.800 lebih rendah</strong> dari neto yang tercetak. Tampilan mempertahankan neto tercetak sambil menandai selisihnya.</p><button class="text-link source-link" data-finance-source="reconciliation">Rincian pemeriksaan ${icon('arrow')}</button></div></section>
 <section class="card reference-section">${cardHead('Kesiapan dokumen Finance','Setiap laporan memiliki cakupan dan kualitas yang berbeda')}<div class="document-grid"><div><span class="eyebrow">DAPAT MEMBANTU RINGKASAN</span><h3>Laba-rugi kompilasi & laporan divisi</h3><p>Perbandingan tahunan, perubahan laba, penggerak beban, dan kontribusi divisi. Subtotal utama GL berhasil direkonsiliasi secara aritmetika.</p>${pill('2 sumber utama','ok')}</div><div><span class="eyebrow">KHUSUS CABANG</span><h3>Laba-rugi C001 Cikupa</h3><p>Subtotal utama memuat #NULL!. Rincian akun bisa membantu penelusuran, tetapi belum digunakan sebagai kartu kinerja.</p>${pill('Perlu ekspor yang diperbaiki','warn')}</div><div><span class="eyebrow">NERACA BELUM SIAP</span><h3>Dua file, isi sel identik</h3><p>Keduanya C001 Cikupa. Subtotal dan sisi kewajiban/ekuitas memuat error; kas perusahaan, rasio lancar, dan modal kerja belum disajikan.</p>${pill('Duplikat · satu dataset','warn')}</div></div><div class="table-foot"><span>File ini belum mendukung tren bulanan/harian atau ranking seluruh toko.</span><button class="text-link" data-finance-source="documents">Telusuri 5 dokumen ${icon('arrow')}</button></div></section>`;
}
function financeFile(id,ref) {
 const source=actual.source.find(s=>s.id===id);
 return `<div class="source-file"><strong>${esc(source.file)}</strong><span>${esc(source.sheet)} · ${esc(ref)}</span></div>`;
}
function openFinanceSource(key) {
 const p=actual.pl,d=actual.divisionTotals;
 let title,body;
 if(p[key]) {
  const r=p[key]; title=r.label;
  body=`<ul class="key-values"><li><span>2025</span><strong>${money(r.current)}</strong></li><li><span>2024</span><strong>${money(r.prior)}</strong></li><li><span>Perubahan nominal</span><strong>${signedMoney(r.current-r.prior)}</strong></li></ul><p>Nilai F = 2025, H = 2024. Dibaca dari hasil numerik yang tersimpan; subtotal utama kedua tahun telah dicek terhadap komponen penyusunnya.</p>${financeFile(4,r.ref)}`;
 } else if(key.startsWith('division-')) {
  const r=actual.divisions.find(d=>String(d.code)===key.slice(9)); if(!r)return;
  title=r.name;
  body=`<ul class="key-values">${[['Kuantitas',count(r.quantity)],['Penjualan bersih',money(r.net)],['HPP rata-rata',money(r.cost)],['Laba kotor',money(r.grossProfit)],['Margin terhadap neto',precisePercent(r.margin*100)]].map(([l,v])=>`<li><span>${l}</span><strong>${v}</strong></li>`).join('')}</ul><p>Penjualan, biaya, dan laba kotor mengikuti nilai yang tercetak pada laporan divisi. HPP rata-rata berbeda dari HPP buku besar.</p>${financeFile(0,r.ref)}`;
 } else if(key.startsWith('driver-')) {
  const r=actual.costDrivers[Number(key.slice(7))];if(!r)return;title=r.label;
  body=`<ul class="key-values"><li><span>2025</span><strong>${money(r.current)}</strong></li><li><span>2024</span><strong>${money(r.prior)}</strong></li><li><span>Kenaikan</span><strong>${money(r.current-r.prior)}</strong></li></ul><p>Angka ini termasuk dalam subtotal beban pada laporan laba-rugi. Ini petunjuk penelusuran; workbook tidak menjelaskan penyebab setiap kenaikan.</p>${financeFile(4,r.ref)}`;
 } else if(key==='expenses') {
  title='Total beban usaha';body=`<div class="formula">Beban usaha + beban usaha lainnya</div><p>2025: ${money(p.opex.current)} + ${money(p.otherOpex.current)} = <strong>${money(p.opex.current+p.otherOpex.current)}</strong>.</p><p>2024: ${money(p.opex.prior+p.otherOpex.prior)}. Tidak memasukkan HPP, nonoperasi, atau pajak penghasilan.</p>${financeFile(4,'F38:I38 dan F125:I125')}`;
 } else if(key==='margin') {
  title='Basis persentase yang konsisten';body=`<div class="formula">Margin = laba ÷ penjualan bersih × 100%</div><p>Margin kotor 2025 pada tampilan ini dihitung dari F36 ÷ F32 = ${precisePercent(p.gross.current/p.sales.current*100)}. Margin bersih memakai F229 ÷ F32 = ${precisePercent(p.profit.current/p.sales.current*100)}.</p><p>Kolom persentase G/I di workbook GL memakai penjualan bruto F9/H9. Karena pembaginya berbeda, persentase itu tidak disalin langsung ke kartu margin.</p>${financeFile(4,'F9:I9; F32:I36; F229:I229')}`;
 } else if(key==='bridge') {
  title='Perubahan laba setelah pajak';body=`<div class="formula">Δ laba kotor − Δ beban usaha − Δ beban lainnya + Δ nonoperasi − Δ pajak</div><p>Jumlah dampak = ${money(p.profit.current-p.profit.prior)}. Perubahan beban bertanda negatif karena kenaikannya mengurangi laba; penurunan pajak memberi dampak positif.</p><p>2024: ${money(p.profit.prior)} → 2025: ${money(p.profit.current)}. Diagram memakai selisih nominal tiap komponen; rincian biaya tidak dijumlahkan kembali.</p>${financeFile(4,'F36:I38; F125:I125; F210:I210; F226:I229')}`;
 } else if(key==='reconciliation') {
  title='Selisih penjualan & HPP';body=`<p>Laporan divisi: neto tercetak ${money(d.net)}. GL kompilasi: ${money(p.sales.current)}. Selisih <strong>${money(d.net-p.sales.current)}</strong>.</p><p>Di laporan divisi, bruto ${money(d.grossSales)} − diskon ${money(d.discount)} − retur ${money(d.returns)} = ${money(d.grossSales-d.discount-d.returns)}, atau Rp244.800 di bawah neto tercetak. Jumlah neto 9 divisi tetap sama dengan total G21.</p><p>HPP divisi lebih rendah ${money(p.cogs.current-d.cost)} dan laba kotornya lebih tinggi ${money(d.grossProfit-p.gross.current)} dibanding GL. Perlu memeriksa cutoff, posting, koreksi, dan metode biaya untuk menjelaskan selisih; belum ada bukti penyebab tunggal.</p>${financeFile(0,'D11:K21')}${financeFile(4,'F9:F36')}`;
 } else {
  title='Lima dokumen Finance';
  const notes={0:'All unit · 9 divisi · HPP rata-rata. Dua #DIV/0! berada pada baris ringkasan batal/void, di luar KPI yang dipakai.',1:'C001 Cikupa · 407 #NULL!. Nilai sel identik dengan file neraca tanpa (1).',2:'C001 Cikupa (J5) · 527 #NULL!, termasuk subtotal utama. Belum dipakai untuk KPI.',3:'C001 Cikupa · duplikat isi sel file neraca (1), bukan unit tambahan. Subtotal neraca belum valid.',4:'Kompilasi unit (A5), 2025/2024 (F7/H7). Subtotal nominal utama valid secara aritmetika. 21 #REF! dan 65 #N/A terdapat pada formula pendukung/rasio, tidak dipakai dalam KPI.'};
  body=`<p>Sumber berasal dari file yang diberikan, tidak diambil dari database operasional. Nilai dibaca dari hasil yang tersimpan dalam workbook; formula Excel tidak dihitung ulang.</p>${actual.source.map(s=>`${financeFile(s.id,s.id===0?'A11:L21':s.id===4?'A5:I229':s.id===2?'J5; F9:I228':'F14:J148')}<p>${notes[s.id]}</p>`).join('')}<div class="section-note">Label “kompilasi” belum membuktikan eliminasi konsolidasi. Ekspor bulanan dan per cabang masih diperlukan untuk tren serta ranking toko.</div>`;
 }
 openDetail(title,body+'<div class="section-note">Angka uang di tampilan dibulatkan; nilai asli disimpan di finance-reference.js. Dokumen sumber tidak diubah.</div>','SUMBER FINANCE · 2025 / 2024');
}
setupShell();readHash();render();
